namespace menu_fonts
{
    namespace
    {
        ImFont* g_regular = nullptr;
        ImFont* g_strong = nullptr;
    }

    void add()
    {
        ImGuiIO& io = ImGui::GetIO();

        ImFontConfig body;
        body.OversampleH = 2;
        body.PixelSnapH = true;

        // Primary UI face.
        g_regular = io.Fonts->AddFontFromMemoryCompressedBase85TTF(SstMedium_compressed_data_base85, 15.0f, &body);
        if (g_regular == nullptr)
            g_regular = io.Fonts->AddFontDefault();

        // Icons are merged into the primary face, so every label can embed glyphs.
        // The merged font is kept as a separate atlas entry, which is why the bold
        // face is cached here instead of being looked up by index.
        ImFontConfig icons;
        icons.MergeMode = true;
        icons.OversampleH = 2;
        icons.PixelSnapH = true;
        io.Fonts->AddFontFromMemoryCompressedBase85TTF(FaSolid_compressed_data_base85, 14.0f, &icons);

        // Bold face used for titles/branding.
        ImFontConfig bold;
        bold.OversampleH = 2;
        bold.PixelSnapH = true;
        g_strong = io.Fonts->AddFontFromMemoryCompressedBase85TTF(SstBold_compressed_data_base85, 16.0f, &bold);
        if (g_strong == nullptr)
            g_strong = g_regular;
    }

    ImFont* strong()
    {
        return g_strong;
    }
}